import{_ as a,o as n,c as t,am as r}from"./chunks/framework.DNUWZnVH.js";const m=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),i={name:"glossaire.md"};function o(s,e,l,u,d,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="agent-de-code" tabindex="-1">Agent de code <a class="header-anchor" href="#agent-de-code" aria-label="Permalink to &quot;Agent de code&quot;">​</a></h3><p>Agent qui lit, modifie et exécute du code dans un dépôt (Copilot, Claude Code, Codex, Cursor…).</p><h3 id="boucle-agentique" tabindex="-1">Boucle agentique <a class="header-anchor" href="#boucle-agentique" aria-label="Permalink to &quot;Boucle agentique&quot;">​</a></h3><p>Le cycle demande → le modèle choisit un tool → le harness l&#39;exécute → le résultat entre dans le contexte → on recommence si besoin.</p><h3 id="ci-integration-continue" tabindex="-1">CI (intégration continue) <a class="header-anchor" href="#ci-integration-continue" aria-label="Permalink to &quot;CI (intégration continue)&quot;">​</a></h3><p>Les vérifications lancées automatiquement à chaque changement du code (construire, tester) avant qu&#39;il parte en production.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="contrat-de-modele" tabindex="-1">Contrat de modèle <a class="header-anchor" href="#contrat-de-modele" aria-label="Permalink to &quot;Contrat de modèle&quot;">​</a></h3><p>Les colonnes et les types qu&#39;un modèle dbt s&#39;engage à fournir. Appliqué (enforced), il fait échouer le build plutôt que de casser en silence ce qui lit le modèle.</p><h3 id="couche-semantique-semantic-layer" tabindex="-1">Couche sémantique (semantic layer) <a class="header-anchor" href="#couche-semantique-semantic-layer" aria-label="Permalink to &quot;Couche sémantique (semantic layer)&quot;">​</a></h3><p>L&#39;endroit où les métriques sont définies une seule fois, au-dessus des modèles, et interrogées par tous les outils (dbt Semantic Layer avec MetricFlow, Cube, LookML).</p><h3 id="data-owner" tabindex="-1">Data owner <a class="header-anchor" href="#data-owner" aria-label="Permalink to &quot;Data owner&quot;">​</a></h3><p>La personne du métier qui répond d&#39;une donnée ou d&#39;un KPI : sa définition, sa qualité attendue. Une seule par KPI.</p><h3 id="dbt" tabindex="-1">dbt <a class="header-anchor" href="#dbt" aria-label="Permalink to &quot;dbt&quot;">​</a></h3><p>Outil qui transforme les données dans l&#39;entrepôt avec des requêtes SQL versionnées (les modèles), les teste et les documente.</p><h3 id="duckdb" tabindex="-1">DuckDB <a class="header-anchor" href="#duckdb" aria-label="Permalink to &quot;DuckDB&quot;">​</a></h3><p>Moteur de base de données analytique qui tourne dans un fichier local, sans serveur : celui du pipeline de l&#39;atelier.</p><h3 id="exposition-exposure" tabindex="-1">Exposition (exposure) <a class="header-anchor" href="#exposition-exposure" aria-label="Permalink to &quot;Exposition (exposure)&quot;">​</a></h3><p>La déclaration, dans dbt, d&#39;un usage en aval (un tableau de bord, une page BI) et de ce dont il dépend : le lignage va jusqu&#39;à l&#39;écran.</p><h3 id="grain" tabindex="-1">Grain <a class="header-anchor" href="#grain" aria-label="Permalink to &quot;Grain&quot;">​</a></h3><p>Ce que représente une ligne d&#39;une table (« une ligne par séjour », « une ligne par paiement »). Un grain flou donne des chiffres qui changent selon qui les calcule.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA <em>avant</em> qu&#39;elle soit utilisée.</p><h3 id="instructions-projet" tabindex="-1">Instructions projet <a class="header-anchor" href="#instructions-projet" aria-label="Permalink to &quot;Instructions projet&quot;">​</a></h3><p>Fichier versionné dans le dépôt, chargé à chaque session : conventions, commandes, pièges (<code>AGENTS.md</code>, <code>CLAUDE.md</code> pour Claude Code). C&#39;est l&#39;équivalent dev des instructions personnalisées.</p><h3 id="kpi" tabindex="-1">KPI <a class="header-anchor" href="#kpi" aria-label="Permalink to &quot;KPI&quot;">​</a></h3><p>Indicateur clé de performance : un chiffre suivi pour piloter, avec une définition écrite et une personne qui en répond.</p><h3 id="lignage-lineage" tabindex="-1">Lignage (lineage) <a class="header-anchor" href="#lignage-lineage" aria-label="Permalink to &quot;Lignage (lineage)&quot;">​</a></h3><p>Le chemin d&#39;une donnée, de sa source aux tableaux de bord qui l&#39;utilisent. Il dit où chercher quand un chiffre est faux, et ce qu&#39;un changement va toucher.</p><h3 id="mart" tabindex="-1">Mart <a class="header-anchor" href="#mart" aria-label="Permalink to &quot;Mart&quot;">​</a></h3><p>La couche de modèles destinée aux usages (BI, analystes) : des tables orientées métier, aux noms compréhensibles.</p><h3 id="mesure-non-additive" tabindex="-1">Mesure non additive <a class="header-anchor" href="#mesure-non-additive" aria-label="Permalink to &quot;Mesure non additive&quot;">​</a></h3><p>Un compte de distincts (membres, clients) ne s&#39;additionne pas d&#39;une ligne à l&#39;autre : la même personne peut figurer sur plusieurs lignes. Le total se calcule au bon grain.</p><h3 id="metricflow" tabindex="-1">MetricFlow <a class="header-anchor" href="#metricflow" aria-label="Permalink to &quot;MetricFlow&quot;">​</a></h3><p>Le moteur de la couche sémantique de dbt : il lit les semantic models et les métriques, et génère le SQL d&#39;une requête (mf query).</p><h3 id="metrique" tabindex="-1">Métrique <a class="header-anchor" href="#metrique" aria-label="Permalink to &quot;Métrique&quot;">​</a></h3><p>Un KPI implémenté dans la couche sémantique : une mesure, un filtre, une description ; on l&#39;interroge par dimensions sans réécrire de SQL.</p><h3 id="modele-intermediaire" tabindex="-1">Modèle intermédiaire <a class="header-anchor" href="#modele-intermediaire" aria-label="Permalink to &quot;Modèle intermédiaire&quot;">​</a></h3><p>Une couche entre le staging et les marts : une logique réutilisable (les séjours terminés, les membres actifs) écrite une seule fois.</p><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><p>Les actions autorisées à l&#39;agent (lire, écrire, lancer une commande, accéder au réseau).</p><h3 id="pull-request-pr" tabindex="-1">Pull request (PR) <a class="header-anchor" href="#pull-request-pr" aria-label="Permalink to &quot;Pull request (PR)&quot;">​</a></h3><p>Une proposition de changement sur une branche, relue avant d&#39;être fusionnée. La revue regarde aussi ce que le changement casse en aval.</p><h3 id="restructuration-refactoring" tabindex="-1">Restructuration (refactoring) <a class="header-anchor" href="#restructuration-refactoring" aria-label="Permalink to &quot;Restructuration (refactoring)&quot;">​</a></h3><p>Changer la structure du code sans changer ce qu&#39;il produit. Elle se prouve en comparant la sortie avant et après.</p><h3 id="saved-query" tabindex="-1">Saved query <a class="header-anchor" href="#saved-query" aria-label="Permalink to &quot;Saved query&quot;">​</a></h3><p>Une requête de la couche sémantique enregistrée (métriques, dimensions, grain), réutilisable et exportable, par exemple pour alimenter une page BI.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="staging" tabindex="-1">Staging <a class="header-anchor" href="#staging" aria-label="Permalink to &quot;Staging&quot;">​</a></h3><p>La première couche de modèles : la source renommée, typée et nettoyée, une vue par source, sans règle métier.</p><h3 id="test-de-donnees" tabindex="-1">Test de données <a class="header-anchor" href="#test-de-donnees" aria-label="Permalink to &quot;Test de données&quot;">​</a></h3><p>Une règle vérifiée sur les données elles-mêmes (unicité, valeurs permises, référentiel) à chaque construction.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (<em>tool calling</em>).</p><h3 id="version-de-modele" tabindex="-1">Version de modèle <a class="header-anchor" href="#version-de-modele" aria-label="Permalink to &quot;Version de modèle&quot;">​</a></h3><p>Deux versions d&#39;un même modèle dbt servies en parallèle, pour changer une colonne sans casser ceux qui lisent l&#39;ancienne, avec une date de fin.</p>',63)])])}const p=a(i,[["render",o]]);export{m as __pageData,p as default};
